export const suits = ['','万','条','筒'];
export const suitOf = value => Math.floor(value / 10);
export const nameOf = value => `${value % 10}${suits[suitOf(value)]}`;
export const faceOf = value => `assets/tiles/${suitOf(value)}-${value % 10}.png`;
export function createDeck(random = Math.random) {
  const deck = [];
  for(let suit=1;suit<=3;suit++) for(let number=1;number<=9;number++) for(let copy=0;copy<4;copy++) deck.push(suit*10+number);
  for(let i=deck.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}
  return deck;
}
export function exchangeIndices(hand) {
  const groups = [1,2,3].map(suit=>hand.map((value,index)=>({value,index})).filter(x=>suitOf(x.value)===suit));
  return groups.filter(g=>g.length>=3).sort((a,b)=>a.length-b.length)[0].slice(0,3).map(x=>x.index);
}
export function chooseMissing(hand) {
  return [1,2,3].sort((a,b)=>hand.filter(v=>suitOf(v)===a).length-hand.filter(v=>suitOf(v)===b).length)[0];
}
export function canWin(hand, missing) {
  if(hand.length!==14 || hand.some(v=>suitOf(v)===missing)) return false;
  const counts = Array(40).fill(0);
  hand.forEach(v=>counts[v]++);
  if(counts.every(n=>n%2===0)) return true;
  function melds(){
    const first=counts.findIndex(n=>n>0);
    if(first===-1)return true;
    if(counts[first]>=3){counts[first]-=3;const ok=melds();counts[first]+=3;if(ok)return true;}
    if(first%10<=7&&counts[first+1]>0&&counts[first+2]>0){counts[first]--;counts[first+1]--;counts[first+2]--;const ok=melds();counts[first]++;counts[first+1]++;counts[first+2]++;if(ok)return true;}
    return false;
  }
  for(let i=11;i<40;i++)if(counts[i]>=2){counts[i]-=2;const ok=melds();counts[i]+=2;if(ok)return true;}
  return false;
}
export function chooseDiscard(hand, missing) {
  const forced=hand.map((v,i)=>({v,i})).filter(x=>suitOf(x.v)===missing);
  const options=forced.length?forced:hand.map((v,i)=>({v,i}));
  const score=v=>hand.filter(x=>x===v).length*3+hand.filter(x=>suitOf(x)===suitOf(v)&&Math.abs(x-v)===1).length*2+hand.filter(x=>suitOf(x)===suitOf(v)&&Math.abs(x-v)===2).length;
  return options.sort((a,b)=>score(a.v)-score(b.v)||b.v-a.v)[0].i;
}
